MultiLanguageSpellData['ru'][284508] = {name = "Облик Бездны", additional_info = "Мгновенное действие\n[q]Активируется в момент применения \"Извержения Бездны\". Усиливает облик Тьмы мощью Бездны, увеличивая наносимый заклинаниями урон на 10% и мгновенно восстанавливая \"Взрыв разума\".\n\n Время действия – 20 сек. \"Всепожирающая чума\" продлевает время действия \"Облика Бездны\" на 2.5 сек."}
