MultiLanguageSpellData['ru'][297572] = {name = "Коварный дар", additional_info = "Мгновенное действие\n[q]Принять дар Н'Зота, повышающий вашу искусность на 275 на 30 сек. Раз в 1 сек. вы получаете эффект \"Страдание\", наносящий 41 ед. урона от темной магии за каждый накопленный эффект. Повторное применение снимает оба эффекта. Время восстановления – ( 120 / 60) мин."}
