MultiLanguageSpellData['ru'][297574] = {name = "Обреченность", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Отбирает у игроков надежду, в результате чего они в течение 10 сек. не могут атаковать и произносить заклинания.\n\n Игроки могут найти потерянную надежду и тем самым прервать действие эффекта."}
