MultiLanguageSpellData['ru'][302982] = {name = "Пространственная рябь", additional_info = "[q0]Азеритовая сущность\nРадиус действия: 25 м\n{Мгновенное действие} {Восстановление: 1 мин}\n[q]Создает в указанном месте азеритовый маяк. Через 2 сек. Сердце Азерот переносит вас к этому маяку и наносит находящимся рядом противникам 1451 ед. урона от огня."}
MultiLanguageSpellData['ru'][302983] = {name = "Пространственная рябь", additional_info = "[q0]Азеритовая сущность\nРадиус действия: 25 м\n{Мгновенное действие} {Восстановление: 1 мин}\n[q]Создает в указанном месте азеритовый маяк. Через 2 сек. Сердце Азерот переносит вас к этому маяку и наносит находящимся рядом противникам 1451 ед. урона от огня.\n\n В течение 10 сек. после телепортации вы получаете на 10% меньше урона."}
MultiLanguageSpellData['ru'][302984] = {name = "Сдвиг реальности", additional_info = "[q0]Азеритовая сущность\n[q]Если в течение 4 сек. вы преодолеваете расстояние, превышающее 25 м, ваша основная характеристика повышается на 47 на [15 + ( 5000 / 1000)] сек.\n\n Срабатывает не чаще раза в 30 сек."}
