MultiLanguageSpellData['ru'][304119] = {name = "Наплечная пластина", additional_info = "Мгновенное действие\n[q]Поглощает до 2400 ед. урона, полученного от атак дальнего боя. Время действия – до отмены.\n\n Можно использовать только в островных экспедициях."}
MultiLanguageSpellData['ru'][304120] = {name = "Жидкая скорость", additional_info = "{Мгновенное действие} {Восстановление: 2 мин}\n[q]Повышает вашу скорость передвижения на 156 на 20 сек.\n\n Можно использовать только в островных экспедициях."}
MultiLanguageSpellData['ru'][304121] = {name = "Противостояние", additional_info = "[q0]Азеритовая сущность\n[q]Обучает вас PvP-таланту и позволяет использовать его против врагов Азерот.\n\nПока вы оглушены, защитный эффект универсальности повышается на 50%.\n\nРассеивая эффекты, прерывая заклинания и применяя эффекты контроля, вы получаете суммирующийся эффект \"Раздор\". Бонус к универсальности от \"Раздора\" увеличивается вдвое на следующие 5 сек."}
