MultiLanguageSpellData['ru'][306873] = {name = "Электроемкость", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Повышает уровень электроемкости жертвы. Если жертва накопит 10 зарядов электроемкости, произойдет \"Электростатический взрыв\", оглушающий жертву на 4 сек. и наносящий союзникам в радиусе 8 м 20 ед. урона от сил природы."}
MultiLanguageSpellData['ru'][306874] = {name = "Цепная молния", additional_info = "Радиус действия: 20 м\nПрименение: 1.5 сек\n[q]Грозовой охотник поражает цель молнией, наносящей 6259 ед. урона от сил природы. Молния также может поразить дополнительные цели в радиусе 8 м."}
MultiLanguageSpellData['ru'][306875] = {name = "Электростатический взрыв", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Уровень электроемкости цели достигает критического, что вызывает мощный \"Электростатический взрыв\". Жертва оглушается на 4 сек., а цель и ее союзники в радиусе 8 м получают 20 ед. урона от сил природы."}
MultiLanguageSpellData['ru'][306876] = {name = "Темный коллапс", additional_info = "Радиус действия: 500 м\nМгновенное действие\n[q]Наносит всем игрокам 312694 ед. урона от темной магии и дает Занеш способности \" Темное вознесение \" и \" Фанатизм \"."}
