MultiLanguageSpellData['ru'][307227] = {name = "Регенерация", additional_info = "Радиус действия: 500 м\nМгновенное действие\n[q]Низшие акиры восполняют 5% своего максимального запаса здоровья раз в 1 сек., если их уровень здоровья падает ниже 20%.\n\n Низшие акиры, призванные во время действия эффекта \" Контроль над коллективным разумом: Ка'зир \", получают \"Регенерацию\" до конца боя."}
