MultiLanguageSpellData['ru'][323911] = {name = "Покрытая рунами кость", additional_info = "[q]Каждая победа над противником дает вам эффект \"Покрытые рунами кости\", уменьшающий получаемый магический урон на 1% на 30 сек.\n По накоплении 5 эффектов:эффектов бонус от связи душ усиливается на 30 сек.\n\nВеликолепная кожа Эмени : при поглощении эффектов находящиеся рядом противники получают 0 ед. урона от темной магии. Урон увеличивается на 1% за каждый эффект.\nХрящевые ноги : прочность щита удваивается.\nПочечный камень возвращения : время восстановления сокращается в два раза быстрее.\nЗагрубевшие ступни : скорость передвижения повышается на 3% вплоть до 30%.\nСкрежещущие зубы : бонус к скорости увеличивается вдвое.\nСерный выброс : длительность эффекта страха продлевается на 2 сек."}
MultiLanguageSpellData['ru'][323912] = {name = "Телепортация к Престолу Примаса", additional_info = nil}
MultiLanguageSpellData['ru'][323913] = {name = "Пульсирующая плоть", additional_info = "[q]Когда вы получаете исцеление или восполняете здоровье союзников, ваша вероятность критического удара повышается на 1% на 10 сек., вплоть до 5%.\n\n Если на вас действуют \"Покрытые рунами кости\", ваша вероятность критического удара повышается еще на 1% за каждый эффект.\n(Восстановление: 1с)"}
MultiLanguageSpellData['ru'][323914] = {name = "Остронить", additional_info = "[q]Ваши атаки и заклинания могут призвать вращающиеся клинки, вызывающие у противников кровотечение, наносящее 500 ед. урона за 5 сек.\n\n Если на вас действуют \"Покрытые рунами кости\", этот урон удваивается."}
MultiLanguageSpellData['ru'][323915] = {name = "Непреклонность ветерана", additional_info = "[q]Когда вы наносите 10 000 ед. урона, вы получаете эффект \"Непреклонность\", который нейтрализует следующий примененный к вам эффект паралича. Эффект сбрасывается при выходе из боя."}
MultiLanguageSpellData['ru'][323916] = {name = "Серный выброс", additional_info = "[q0]Способность медиума\n[q]Когда ваш уровень здоровья падает ниже 20%, вы на 3.5 сек повергаете находящихся рядом противников в ужас. Срабатывает не чаще раза в 60 сек."}
MultiLanguageSpellData['ru'][323917] = {name = "Черный список", additional_info = "[q]Когда вы наносите цели 10 000 ед. урона, она попадает в ваш черный список.\n Победа над противниками из черного списка на 30 сек. повышает вашу вероятность критического удара на 100 вплоть до 1000."}
MultiLanguageSpellData['ru'][323918] = {name = "Загрубевшие ступни", additional_info = "[q0]Способность медиума\n[q]Повышает скорость передвижения на 3% за каждого находящегося рядом противника, вплоть до 15%."}
MultiLanguageSpellData['ru'][323919] = {name = "Скрежещущие зубы", additional_info = "[q0]Способность медиума\n[q]Когда вы побеждаете противников, ваша скорость повышается на 3% на 10 сек., вплоть до 15%."}
