MultiLanguageSpellData['ru'][325019] = {name = "Горное дело Темных Земель", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Обучает добыче руды и камней из минеральных жил. Эти материалы используются в инженерном и кузнечном деле. Позволяет развить навык горного дела до 150."}
MultiLanguageSpellData['ru'][325020] = {name = "Кольцо перерождения", additional_info = "[q0]Способность ковенанта\nМгновенное действие\n[q]Выпускает выброс анимы, нанося до (74% of Spell power) ед. урона от тайной магии в зависимости от числа противников, и восполняя максимум 6 союзникам (24% of Spell power) ед. здоровья. Радиус действия – 8 м.\n\n Дает 1 эффекта:эффектов \"Благословение перерожденных\" за каждую получившую урон цель."}
