MultiLanguageSpellData['ru'][329589] = {name = "Пространственный диссонанс", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Наносит противникам в радиусе 5 м 9684 ед. урона от тайной магии и закрывает находящиеся рядом разломы пожирателей.\n\n Если эта способность поражает пожирателя на Погосте древней, его анима дестабилизируется, в результате чего наносимый им урон уменьшается на 50 %, а получаемый урон увеличивается на 200 %. Время действия – 1 мин."}
MultiLanguageSpellData['ru'][329590] = {name = "Ядро элементаля", additional_info = "[q0]Сила анимы\nМгновенное действие\n[q]Каждый поглощенный эффект [ Выброс лавы : \"Волны лавы\" / \"Вестника шторма\"] увеличивает урон от [ Выброс лавы : \"Выброса лавы\" / \"Удара бури\"] на 3%. После накопления 20 эффектов время восстановления [ Выброс лавы : \"Выброса лавы\" / \"Удара бури\"] будет сокращено на 50%."}
