MultiLanguageSpellData['ru'][335450] = {name = "Пепельный ползун", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]После убийства 10 противников вы призываете пепельного ползуна, который помогает вам в бою. За каждого противника, которого вы побеждаете совместно с ползуном, наносимый им урон увеличивается на 2%, при этом он восполняет 10% запаса здоровья. Иным способом ползуна исцелить нельзя."}
MultiLanguageSpellData['ru'][335451] = {name = "[q5]Добиватель", additional_info = "Сила рун\n[q2]\"Казнь\" увеличивает урон, который цель получает от вашего следующего \"Смертельного удара\", на 50%. Суммируется до 2 раз.\n[q]Вырезание рун: Плечи, Палец\n[q]Источник: Добыча из рейда: сир Денатрий"}
